type Client={id:string|number;name:string;company:string;email:string;phone:string;address:string;taxId:string;notes:string;projects:number;value:number;last:string}
type Project={id:string|number;client_id?:string;client:string;title:string;slug:string;type:string;category:string;status:string;published:boolean;description?:string;budget?:number;deadline?:string}
type Team={id:string|number;name:string;specialty:string;email:string;phone?:string;active:boolean;image_url?:string}
type Shoot={id:string|number;project_id?:string;project:string;title:string;starts_at:string;location:string;status:string;notes?:string}
type Gear={id:string|number;name:string;category:string;serial_number:string;quantity:number;status:string;image_url?:string}
type Campaign={id:string|number;name:string;channel:'EMAIL'|'SMS';subject?:string;message:string;status:string;recipient_count:number}
type LineItem={id?:string;description:string;quantity:number;unitPrice:number}
type Invoice={dbId?:string;number:string;clientId:string;client:string;clientEmail:string;label:string;subtotal:number;tax:number;total:number;amountPaid:number;due:string;issueDate:string;status:'BROUILLON'|'ENVOYÉE'|'PAYÉE'|'EN RETARD';items:LineItem[]}
type Quote={dbId?:string;number:string;clientId:string;client:string;label:string;total:number;date:string;status:'BROUILLON'|'ENVOYÉ'|'ACCEPTÉ'}
type MediaAsset={id:string|number;path?:string;bucket?:string;name:string;src:string;type:'PHOTO'|'VIDÉO'|'PDF';project:string;projectId?:string}
type DownloadRecord={id:string;kind:string;created_at:string;project?:{title:string}|null;media?:{storage_path:string}|null}
type ClientLink={id:string;project_id:string;expires_at?:string;download_enabled:boolean;active:boolean;project?:{title:string;client?:{company?:string;name?:string}}|null}
type Analytics={views:number;downloads:number;inquiries:number;galleries:number}
type EntitySheet='client'|'project'|'team'|'shoot'|'gear'|'campaign'|'quote'|null

const asset=(path:string)=>`${import.meta.env.BASE_URL}${path.replace(/^\//,'')}`
const money=(n:number)=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(n)+' GNF'
const shortDate=(value:string)=>value?new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value)):'—'
const dateTime=(value:string)=>new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value))
const today=()=>new Date().toISOString().slice(0,10)
const plusDays=(days:number)=>{const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}

