 const [sheet,setSheet]=useState<EntitySheet>(null),[editingClient,setEditingClient]=useState<Client|null>(null),[invoiceBuilder,setInvoiceBuilder]=useState(false),[linkBuilder,setLinkBuilder]=useState(false),[createdLink,setCreatedLink]=useState<{url:string;pin:string}|null>(null),[selectedClientId,setSelectedClientId]=useState<string>(''),[selectedInvoiceNumber,setSelectedInvoiceNumber]=useState<string>('')
