 setProjects(projectRows.map((p:any)=>({id:p.id,client_id:p.client_id,client:p.client?.company||p.client?.name||'Interne',title:p.title,slug:p.slug,type:p.project_type,category:p.project_type,status:p.status,published:p.published,description:p.description,budget:Number(p.budget||0),deadline:p.deadline||''})))
 if(!tr.error)setTeams(tr.data||[]);if(!sr.error)setShoots((sr.data||[]).map((s:any)=>({...s,project:s.project?.title||'Sans projet'})));if(!gr.error)setGear(gr.data||[]);if(!cor.error)setCampaigns(cor.data||[])
